import infer from "subatom-infer";

// Validates POST /api/v1/resumes/track-ai
export const trackAiFeatureSchema = {
  body: {
    userId: infer.string().min(1),
    resumeId: infer.string().min(1),
    featureKey: infer.string(), // validated against an allow-list in the controller
  },
};

// Validates GET /api/v1/resumes/:resumeId/ai-usage
export const getAiUsageParamSchema = {
  params: {
    resumeId: infer.string().min(1),
  },
  query: {
    userId: infer.string().min(1),
  },
};

// Validates POST /api/v1/resumes/finalize-and-deduct
export const finalizeResumeAiSchema = {
  body: {
    userId: infer.string().min(1),
    resumeId: infer.string().min(1),
    // Client draft id (send "" if none). Lets the server merge usage tracked
    // before the resume had a real Mongo id.
    draftId: infer.string(),
  },
};
